  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 6, 'Como avaliar razões, evidências e conclusões', 'Uma conclusão convincente não se sustenta apenas por soar familiar. Identifique as razões, verifique como se conectam à conclusão e pergunte se a evidência cobre o alcance da afirmação.', '## 1. Reconstrua o argumento
Localize o que se pretende defender e quais razões são oferecidas. “Porque”, “já que” e “uma vez que” costumam introduzir premissas; “portanto” e “por isso” podem sinalizar conclusão. As palavras ajudam, mas a função de cada frase no raciocínio é decisiva.

## 2. Teste pertinência e suficiência
Uma razão pode ser verdadeira e ainda não apoiar a conclusão. Pergunte se ela trata do ponto em debate e se, junto às outras razões, é suficiente para o alcance afirmado. Um relato pode revelar uma barreira sem estimar sua frequência; uma medida local pode orientar uma hipótese sem provar uma regra para toda a cidade.

## 3. Separe forma, premissas e força
Em um argumento dedutivo válido, não é possível que todas as premissas sejam verdadeiras e a conclusão falsa. Isso não prova que as premissas são verdadeiras. Argumentos indutivos não garantem a conclusão, mas podem torná-la mais provável quando os dados são pertinentes, representativos e considerados com alternativas.

## 4. Procure pressupostos e explicações alternativas
Pergunte o que precisa ser verdadeiro para a passagem funcionar. Compare amostras, condições iniciais, causas concorrentes, contraexemplos e diferenças entre casos usados em analogias. Um teste bom mira a ligação entre as razões e a conclusão, não a pessoa que falou.

## 5. Calibre a conclusão
Não é preciso escolher entre certeza total e rejeição completa. Diga o que a evidência apoia, em quais condições e o que ainda falta. Uma recomendação normativa também depende de critérios ou valores: dados ajudam a prever efeitos, mas não determinam sozinhos qual distribuição é justa ou qual custo é aceitável.

## Exemplo resolvido
Uma cidade testa uma nova rota de ônibus por um mês. A contagem mostra mais embarques após as 20h e algumas pessoas relatam que conseguiram chegar ao trabalho. A conclusão “a rota pode atender uma necessidade noturna” é compatível com os dados. Já “a rota deve permanecer em todas as regiões, sem mudanças” é mais ampla: seria preciso olhar dias e locais diferentes, comparar custos e alternativas, identificar quem depende da linha e explicitar o critério público usado para decidir. As evidências informam a decisão, mas o relatório deve limitar a conclusão ao que foi medido e declarar o valor que orienta a recomendação.',
    'No teste de ônibus, “houve mais embarques depois das 20h” é um dado e “a rota pode atender uma necessidade” é uma inferência plausível. Para recomendar a permanência universal, faltam comparação por região, custo, alternativas e um critério de acesso. A boa análise aceita a evidência limitada sem transformá-la em prova de uma política muito mais ampla.', array['Escreva a conclusão em uma frase e numere cada razão.', 'Para cada razão, pergunte: é pertinente? é confiável? cobre o alcance?', 'Tente imaginar um contraexemplo ou uma causa alternativa.', 'Conclua com uma formulação proporcional à força da evidência.']::text[], 28, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-philosophy-evaluate-argument","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Reconhecer afirmações e razões em um texto.","Compreender que uma conclusão pode depender de mais de uma premissa.","Distinguir observação de recomendação."],"key_concepts":["premissas e conclusão","pertinência e suficiência","validade e verdade das premissas","força indutiva e representatividade","causalidade e explicações alternativas","contraexemplos e analogias","alcance proporcional da conclusão"],"progression":[{"stage":"FOUNDATION","focus":"Localizar conclusões, premissas e dados pertinentes.","questionIds":["v5-phil-argument-probe-01","v5-phil-argument-probe-02"]},{"stage":"APPLICATION","focus":"Testar suficiência, amostras, causas e pressupostos em argumentos cotidianos.","questionIds":["v5-phil-argument-practice-01","v5-phil-argument-practice-02","v5-phil-argument-practice-03","v5-phil-argument-practice-04"]},{"stage":"TRANSFER","focus":"Avaliar políticas e relatórios com efeitos distribuídos e evidência de alcance limitado.","questionIds":["v5-phil-argument-transfer-01","v5-phil-argument-transfer-02","v5-phil-argument-transfer-03","v5-phil-argument-transfer-04"]},{"stage":"INTEGRATION","focus":"Distinguir validade, verdade, princípios normativos e qualidade de evidência.","questionIds":["v5-phil-argument-lock-01","v5-phil-argument-lock-02"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Revisar argumentos em contextos novos e calibrar conclusões diante de dados mistos.","questionIds":["v5-phil-argument-review-01","v5-phil-argument-review-02","v5-phil-argument-review-03","v5-phil-argument-review-04","v5-phil-argument-review-05","v5-phil-argument-review-06","v5-phil-argument-review-07","v5-phil-argument-review-08"]}],"micro_explanations":[{"trigger":"PREMISE_OR_CONCLUSION","text":"Pergunte qual afirmação o texto quer que o leitor aceite; as demais podem funcionar como razões."},{"trigger":"RELEVANCE_OR_TRUTH","text":"Uma afirmação verdadeira só ajuda se tiver relação com a conclusão em debate."},{"trigger":"VALIDITY_OR_PREMISE_TRUTH","text":"Validade examina a forma da inferência; veracidade e justificativa das premissas exigem outra checagem."},{"trigger":"CORRELATION_OR_CAUSE","text":"Uma mudança depois de outra pode sugerir hipótese; compare causas concorrentes e condições iniciais."},{"trigger":"EVIDENCE_SCOPE","text":"Compare quem foi observado com o grupo descrito na conclusão."},{"trigger":"FACT_OR_NORM","text":"Um dado descreve o que ocorre; uma recomendação também precisa explicitar critérios e valores."}],"remediations":[{"id":"MAP_PREMISES","misconception":"PREMISSA_TROCADA_POR_CONCLUSAO","prompt":"Reescreva o texto em duas linhas: “As razões são...” e “A conclusão é...”. Que palavra ou relação indica a passagem?"},{"id":"TEST_ALTERNATIVE","misconception":"CAUSALIDADE_SEM_COMPARACAO","prompt":"Liste uma causa alternativa e diga qual comparação ou dado ajudaria a distingui-la da explicação proposta."},{"id":"LIMIT_GENERALIZATION","misconception":"ALCANCE_MAIOR_QUE_AMOSTRA","prompt":"Descreva quem foi observado, quem não respondeu e para qual população a conclusão pretende valer."},{"id":"CALIBRATE_CONCLUSION","misconception":"DADO_DESCRITIVO_VIRA_OBRIGACAO","prompt":"Separe o fato medido da ação recomendada. Qual critério normativo liga os dois e quais alternativas precisam ser comparadas?"}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Informal Logic","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/logic-informal/","accessedOn":"2026-10-13","supports":["Análise de argumentos em contextos reais.","Avaliação de razões, evidências, provas e justificações."],"use":"Fonte conceitual para desenvolver avaliação contextual de argumentos; não fornece alinhamento oficial BNCC."},{"title":"Argument","publisher":"Internet Encyclopedia of Philosophy","url":"https://iep.utm.edu/argument/","accessedOn":"2026-10-13","supports":["Reconstrução de premissas e conclusão.","Avaliação de argumentos fora de exemplos puramente formais."],"use":"Apoio para a estrutura didática de reconstrução e avaliação; itens e exemplos do pacote são autorais."},{"title":"Fallacies","publisher":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/fallacies/","accessedOn":"2026-10-13","supports":["Cuidado ao aplicar rótulos de falácia sem analisar o contexto e a função argumentativa."],"use":"Evita tratar listas de rótulos como substituto de avaliação; revisão pedagógica humana permanece pendente."}],"copyright_note":"Questões, exemplos e explicações deste pacote são autorais. As fontes apoiam o rigor conceitual; mapeamento oficial e revisão pedagógica humana não foram aprovados.","source_question_feedback":[{"questionId":"v3-philosophy-philosophy_argument-1","hint":"Explicite o critério usado para distribuir e examine quem é afetado por cada alternativa.","errorFocus":"Tomar uma preferência ou divisão aparentemente igual como justificativa completa de justiça."},{"questionId":"v3-philosophy-philosophy_argument-2","hint":"Separe a condição inicial da afirmação que decorre dela após a palavra “logo”.","errorFocus":"Trocar uma premissa pela conclusão que o argumento pretende sustentar."},{"questionId":"v3-philosophy-philosophy_argument-3","hint":"Teste primeiro se a conclusão pode ser falsa quando as premissas são verdadeiras; depois confira cada premissa.","errorFocus":"Confundir forma válida com premissas verdadeiras ou argumento sólido."},{"questionId":"v3-philosophy-philosophy_argument-4","hint":"Identifique qual ponto foi questionado e se a resposta oferece uma razão para ele.","errorFocus":"Tratar uma objeção como ataque pessoal em vez de oportunidade de testar a inferência."},{"questionId":"v3-philosophy-philosophy_argument-6","hint":"Liste a semelhança que sustenta a comparação e um limite relevante para a conclusão.","errorFocus":"Aceitar a analogia só porque os dois casos compartilham alguma característica."},{"questionId":"v3-philosophy-philosophy_argument-7","hint":"A dúvida metodológica suspende a aceitação até haver critério; não afirma que nenhuma afirmação pode ser avaliada.","errorFocus":"Confundir pedido de evidência com negação indiscriminada."},{"questionId":"v3-philosophy-philosophy_argument-8","hint":"Considere quais condições sociais influenciam a escolha sem concluir automaticamente que toda autonomia desaparece.","errorFocus":"Tratar influência contextual como prova de ausência total de autonomia."},{"questionId":"v3-philosophy-philosophy_argument-9","hint":"Compare a previsão com dados verificáveis e com a possibilidade de outras pessoas examinarem a evidência.","errorFocus":"Confundir palpite e conhecimento sem perguntar pelas razões e pela qualidade da evidência."},{"questionId":"v3-philosophy-philosophy_argument-10","hint":"Avalie as razões apresentadas para a proposta, não um erro sem relação cometido pelo autor.","errorFocus":"Rejeitar uma conclusão atacando a pessoa, sem responder às premissas."},{"questionId":"v3-philosophy-philosophy_argument-11","hint":"Formule a conclusão, encontre as razões e procure evidência ou contraexemplo pertinente.","errorFocus":"Aceitar ou rejeitar uma afirmação viral apenas pela popularidade."},{"questionId":"v3-philosophy-philosophy_argument-12","hint":"Pergunte quantos casos foram observados e se eles representam a população mencionada.","errorFocus":"Usar um caso ilustrativo como estimativa de toda uma cidade."},{"questionId":"v4-authored-philosophy-review-01","hint":"Verifique se a autoridade oferece dados ou razões pertinentes; a reputação não substitui a análise.","errorFocus":"Aceitar uma afirmação só pela identidade de quem fala."},{"questionId":"v9-philosophy-argument-01","hint":"A conclusão é a recomendação defendida; a oração seguinte à conjunção explica por quê.","errorFocus":"Selecionar o motivo em vez da proposta que o motivo sustenta."},{"questionId":"v9-philosophy-argument-02","hint":"Observe tamanho e seleção do grupo antes de generalizar para todos os estudantes.","errorFocus":"Tratar poucos colegas voluntários como amostra representativa."},{"questionId":"v9-philosophy-argument-03","hint":"A ordem temporal permite levantar hipótese, mas verifique outras mudanças e uma comparação adequada.","errorFocus":"Concluir causalidade apenas porque o aumento ocorreu depois da instalação."},{"questionId":"v9-philosophy-argument-04","hint":"Procure um caso que restrinja a liberdade e ainda proteja um direito ou condição justa.","errorFocus":"Assumir que uma propriedade geral das regras determina sozinha sua justiça."},{"questionId":"v9-philosophy-argument-05","hint":"Busque evidência que documente a barreira e o efeito do recurso sobre o acesso.","errorFocus":"Escolher um dado sem relação direta com a justificativa de acessibilidade."},{"questionId":"v9-philosophy-argument-06","hint":"Teste se a semelhança afeta disponibilidade e uso compartilhado e considere diferenças práticas.","errorFocus":"Confundir semelhança superficial com analogia justificadora."},{"questionId":"v9-philosophy-argument-07","hint":"Nomeie os grupos, os encargos distribuídos e os princípios que poderiam justificar a escolha.","errorFocus":"Usar a quantidade de beneficiados como única razão decisiva."},{"questionId":"v9-philosophy-argument-08","hint":"A crítica discutida é o custo; verifique se a resposta oferece dados sobre ele.","errorFocus":"Confundir ataque à competência do crítico com resposta à objeção."},{"questionId":"v9-philosophy-argument-09","hint":"Compare objetivo, efeitos sobre direitos, proporcionalidade e alternativas menos restritivas.","errorFocus":"Avaliar uma regra sem explicitar objetivo ou alternativas disponíveis."},{"questionId":"v9-philosophy-argument-10","hint":"Os relatos tratam de segurança; confira se frequência, local e condições sustentam o alcance da conclusão.","errorFocus":"Tratar evidência pertinente como prova completa sem avaliar suficiência."},{"questionId":"v9-philosophy-argument-11","hint":"Pergunte se a diferença muda a razão da regra e se uma exceção pode ser explicada pelo mesmo princípio.","errorFocus":"Aplicar uma regra sem testar se o caso difere de modo relevante."},{"questionId":"v9-philosophy-argument-12","hint":"Separe a medida descritiva da avaliação normativa e explicite o critério de justiça.","errorFocus":"Inferir justiça diretamente de aumento de participação."},{"questionId":"v9-philosophy-argument-13","hint":"Examine a forma inferencial e, em seguida, a confiabilidade da premissa contestada.","errorFocus":"Supor que validade lógica torna verdadeira toda premissa."},{"questionId":"v93-phil-argument-01","hint":"Identifique o que o trecho atribui ao horário ampliado e separe essa conclusão da informação de que a biblioteca abriu mais tarde.","errorFocus":"Repetir a premissa sobre horário em vez de localizar a afirmação sustentada."},{"questionId":"v93-phil-argument-02","hint":"Assuma as premissas apenas para testar a forma: se forem verdadeiras, a conclusão segue para o caso das baleias?","errorFocus":"Deixar um conhecimento sobre baleias substituir a avaliação da relação lógica."},{"questionId":"v93-phil-argument-03","hint":"Separe validade da forma e verdade das premissas; verifique qual premissa compromete a solidez.","errorFocus":"Supor que uma forma válida torna verdadeiras todas as premissas."},{"questionId":"v93-phil-argument-04","hint":"Escolha informação diretamente ligada à circulação e à experiência de acesso, não a uma característica decorativa.","errorFocus":"Selecionar um dado verdadeiro, mas irrelevante para a barreira de acesso."},{"questionId":"v93-phil-argument-05","hint":"Descreva primeiro os 18 respondentes; depois pergunte se a consulta voluntária representa os 900 estudantes.","errorFocus":"Converter a proporção de respondentes em estimativa da população sem amostragem adequada."},{"questionId":"v93-phil-argument-06","hint":"As duas vendas podem variar com uma terceira condição, como calor; associação não estabelece qual evento causa o outro.","errorFocus":"Confundir variação conjunta com uma relação causal direta."},{"questionId":"v93-phil-argument-07","hint":"Avalie a proposta pelas razões e efeitos apresentados; impaciência da pessoa não responde ao conteúdo.","errorFocus":"Usar um traço do proponente como refutação da proposta."},{"questionId":"v93-phil-argument-08","hint":"Procure alternativas entre cancelamento total e ausência completa de prevenção.","errorFocus":"Aceitar como exaustivas duas opções formuladas pelo argumento."},{"questionId":"v93-phil-argument-09","hint":"A conclusão amplia uma observação para casos não observados; mantenha-a provisória e compare fatores relevantes.","errorFocus":"Tratar uma generalização indutiva como necessidade dedutiva."},{"questionId":"v93-phil-argument-10","hint":"Rastreie a origem, procure fontes independentes e verifique evidências específicas para uma afirmação tão ampla.","errorFocus":"Usar popularidade ou confiança do autor como substituto de evidência."},{"questionId":"v93-phil-argument-11","hint":"Mude uma variável relevante e mantenha condições comparáveis, para que o efeito da luz possa ser interpretado.","errorFocus":"Alterar várias condições ao mesmo tempo e atribuir o resultado a uma delas."},{"questionId":"v93-phil-argument-12","hint":"O relato sustenta algo sobre a experiência daquela pessoa; eficácia geral e causalidade exigem evidência adicional.","errorFocus":"Generalizar de um testemunho individual para todas as pessoas."},{"questionId":"v93-phil-argument-13","hint":"Uma definição descreve a estrutura ou função da categoria; um episódio particular é apenas um exemplo.","errorFocus":"Confundir um caso de debate com uma explicação do que é um argumento."},{"questionId":"v93-phil-argument-14","hint":"Um contraexemplo precisa pertencer à categoria e não satisfazer a afirmação universal.","errorFocus":"Escolher um exemplo que confirma a regra em vez de um caso que a refuta."},{"questionId":"v93-phil-argument-15","hint":"“Necessário” quer dizer que sem a credencial não se entra; isso não garante, por si, aprovação na prova.","errorFocus":"Converter uma condição necessária em condição suficiente para outro resultado."},{"questionId":"v93-phil-argument-16","hint":"Procure a recomendação sobre o que a cidade deve fazer; contagens e descrições não são, sozinhas, uma norma.","errorFocus":"Confundir um fato observado com uma obrigação."},{"questionId":"v93-phil-argument-17","hint":"Pergunte qual sentido de “igualmente” está em jogo e quais critérios de distribuição ele implica.","errorFocus":"Ignorar que uma palavra-chave pode encobrir critérios distintos."},{"questionId":"v93-phil-argument-18","hint":"O gráfico mostra uma associação; investigue variáveis concorrentes antes de afirmar uma causa.","errorFocus":"Atribuir causalidade exclusiva a uma variável observada junto com o resultado."},{"questionId":"v93-phil-argument-19","hint":"Compare a composição da turma com as escolas, séries e contextos sobre os quais a recomendação pretende valer.","errorFocus":"Generalizar de um grupo local sem verificar representatividade."},{"questionId":"v93-phil-argument-20","hint":"Relate convergências entre métodos e declare que o desenho não acompanhou mudanças temporais.","errorFocus":"Afirmar evolução ou causa no tempo sem observações longitudinais."}],"objective":"Reconstruir a conclusão e suas premissas, avaliar a pertinência e a suficiência das razões, verificar inferências e limitar a conclusão ao que as evidências sustentam.","common_mistake":"Aceitar ou rejeitar o argumento por quem o apresentou, por uma palavra como “falácia” ou por uma evidência isolada, sem reconstruir a ligação e o alcance da conclusão.","estimated_minutes":28}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 6
     and metadata->>'content_id' = 'v5-philosophy-evaluate-argument' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-phil-argument-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"EVENING_BUS_ROUTE","statement":"Um conselho analisa um texto: “A linha de ônibus atende muitos trabalhadores depois das 20h; por isso, a cidade deve restaurar a última viagem.” Qual afirmação é a conclusão defendida?","options":["A cidade deve restaurar a última viagem da linha.","A linha atende trabalhadores depois das 20h.","O texto menciona um conselho municipal.","Toda linha deve operar durante a madrugada."],"correctAnswer":"A cidade deve restaurar a última viagem da linha.","explanation":"A primeira oração oferece uma razão; a recomendação introduzida por “por isso” é o ponto que o autor quer sustentar.","errorFocus":"Tomar a premissa informativa como se fosse a conclusão do argumento.","hint":"Pergunte qual frase o autor pretende que o conselho aceite, e não qual frase apresenta um dado.","misconceptions":{"A linha atende trabalhadores depois das 20h.":["TOMAR_A_PREMISSA_INFORMATIVA_COMO_SE_FOSSE_A_CONCLUS_O_DO_ARGUMENTO"]},"position":1},{"id":"v5-phil-argument-probe-02","purpose":"PROBE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"CLINIC_EXTENDED_HOURS","statement":"Uma associação pede que uma clínica comunitária amplie o atendimento até as 19h. Qual dado se relaciona mais diretamente à razão apresentada?","options":["A cor preferida dos cartazes da clínica é verde.","Registros mostram que muitos pacientes que trabalham deixam de comparecer porque o atendimento termina antes do fim do expediente.","O prédio foi inaugurado há mais de vinte anos.","Uma clínica de outra cidade tem uma fachada maior."],"correctAnswer":"Registros mostram que muitos pacientes que trabalham deixam de comparecer porque o atendimento termina antes do fim do expediente.","explanation":"O registro conecta o horário atual ao obstáculo descrito. Os demais dados podem ser verdadeiros, mas não sustentam essa recomendação.","errorFocus":"Confundir informação verdadeira com evidência pertinente à conclusão.","hint":"Compare cada dado com a razão prática oferecida para mudar o horário.","misconceptions":{"A cor preferida dos cartazes da clínica é verde.":["CONFUNDIR_INFORMA_O_VERDADEIRA_COM_EVID_NCIA_PERTINENTE_CONCLUS_O"]},"position":2},{"id":"v5-phil-argument-practice-01","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"ARCHIVE_DIGITIZATION","statement":"A equipe afirma: “Digitalizar os documentos reduz o tempo de busca. Este arquivo tem documentos consultados diariamente. Portanto, digitalizar este arquivo deve economizar tempo da equipe.” Qual é a conclusão?","options":["Documentos são consultados diariamente.","A equipe afirma que a busca pode ser reduzida.","Digitalizar este arquivo deve economizar tempo da equipe.","Todo documento digital é mais confiável que o original."],"correctAnswer":"Digitalizar este arquivo deve economizar tempo da equipe.","explanation":"As duas primeiras afirmações funcionam como razões; a recomendação final é a conclusão.","errorFocus":"Selecionar uma premissa em vez da afirmação que depende das razões.","hint":"Localize o que segue de “portanto”.","misconceptions":{"Documentos são consultados diariamente.":["SELECIONAR_UMA_PREMISSA_EM_VEZ_DA_AFIRMA_O_QUE_DEPENDE_DAS_RAZ_ES"]},"position":1},{"id":"v5-phil-argument-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"PUBLIC_CHARGER_ANALOGY","statement":"Uma cidade compara os pontos públicos de recarga de bicicletas a bebedouros: ambos precisam ser localizáveis e distribuídos perto de quem os usa. Que pergunta melhor testa a analogia para decidir onde instalar recargas?","options":["Os dois equipamentos podem ter a mesma cor?","Alguns moradores gostam mais de bicicletas do que de água?","A cidade já usou a palavra “público” em outros projetos?","As necessidades de acesso e os padrões de uso são semelhantes nos aspectos relevantes, ou as recargas exigem critérios diferentes de rede e segurança?"],"correctAnswer":"As necessidades de acesso e os padrões de uso são semelhantes nos aspectos relevantes, ou as recargas exigem critérios diferentes de rede e segurança?","explanation":"Uma analogia sustenta uma conclusão quando a semelhança é relevante para a decisão. Diferenças de energia, segurança e permanência podem limitar a comparação.","errorFocus":"Avaliar uma analogia por semelhanças superficiais, não por sua relevância para a conclusão.","hint":"Identifique qual propriedade compartilhada justificaria a mesma regra e procure diferenças que afetem esse critério.","misconceptions":{"Os dois equipamentos podem ter a mesma cor?":["AVALIAR_UMA_ANALOGIA_POR_SEMELHAN_AS_SUPERFICIAIS_N_O_POR_SUA_RELEV_NCIA_PARA_A_CONCLUS_O"]},"position":2},{"id":"v5-phil-argument-practice-03","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"SCHOOL_MEAL_SURVEY","statement":"Uma comissão diz que deve ampliar o cardápio vegetariano porque uma enquete recebeu muitos votos favoráveis. Qual informação fortaleceria melhor essa razão sem supor que a enquete represente toda a escola?","options":["A taxa de resposta, a composição dos participantes e a comparação entre preferências declaradas e refeições efetivamente escolhidas.","A quantidade de curtidas em uma publicação sem relação com o cardápio.","O nome da empresa que imprimiu os formulários.","A opinião de uma pessoa que não participou da enquete."],"correctAnswer":"A taxa de resposta, a composição dos participantes e a comparação entre preferências declaradas e refeições efetivamente escolhidas.","explanation":"A força da evidência depende de quem respondeu, de quantas pessoas foram ouvidas e de como as respostas se relacionam ao comportamento que a decisão pretende mudar.","errorFocus":"Tratar o número bruto de votos como medida suficiente da população e do efeito esperado.","hint":"Pergunte quem respondeu, quem ficou de fora e se a medida observada corresponde à conclusão.","misconceptions":{"A quantidade de curtidas em uma publicação sem relação com o cardápio.":["TRATAR_O_N_MERO_BRUTO_DE_VOTOS_COMO_MEDIDA_SUFICIENTE_DA_POPULA_O_E_DO_EFEITO_ESPERADO"]},"position":3},{"id":"v5-phil-argument-practice-04","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"OPTIONAL_TUTORING_RESULTS","statement":"Alunos que frequentaram uma tutoria tiveram notas maiores no trimestre. A coordenação conclui que a tutoria causou a diferença. Qual análise é necessária antes de aceitar essa conclusão causal?","options":["Aceitar a causa porque a tutoria ocorreu antes da prova.","Comparar as condições iniciais e outras diferenças entre participantes e não participantes, além de examinar evolução em períodos comparáveis.","Comparar apenas a maior nota de cada grupo.","Ignorar a frequência e atribuir toda diferença à motivação."],"correctAnswer":"Comparar as condições iniciais e outras diferenças entre participantes e não participantes, além de examinar evolução em períodos comparáveis.","explanation":"A sequência temporal não elimina seleção: estudantes que procuram tutoria podem diferir em apoio, tempo de estudo ou desempenho inicial. Comparações melhores ajudam a avaliar explicações alternativas.","errorFocus":"Tomar precedência temporal como prova suficiente de causalidade.","hint":"Liste uma explicação alternativa para a diferença além da tutoria e diga quais dados a distinguiriam.","misconceptions":{"Aceitar a causa porque a tutoria ocorreu antes da prova.":["TOMAR_PRECED_NCIA_TEMPORAL_COMO_PROVA_SUFICIENTE_DE_CAUSALIDADE"]},"position":4},{"id":"v5-phil-argument-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"HEAT_ALERT_OUTCOMES","statement":"Uma equipe afirma que alertas de calor reduzem atendimentos de emergência. Em dois bairros, os atendimentos caíram após uma campanha. Qual dado adicional é mais útil para testar a inferência?","options":["O número de cores usadas nos cartazes.","A quantidade de reuniões da equipe, sem relação com atendimentos.","Séries de períodos comparáveis, bairros sem a campanha e mudanças simultâneas como temperatura, acesso a serviços e composição da população.","Uma declaração de que a campanha foi bem recebida por seus autores."],"correctAnswer":"Séries de períodos comparáveis, bairros sem a campanha e mudanças simultâneas como temperatura, acesso a serviços e composição da população.","explanation":"Uma comparação temporal e entre grupos ajuda a separar o possível efeito do alerta de clima, tendências e mudanças de acesso.","errorFocus":"Generalizar uma mudança posterior à campanha sem comparação que controle outras causas plausíveis.","hint":"Procure o que também mudou no mesmo período e com que grupo ou período comparar.","misconceptions":{"O número de cores usadas nos cartazes.":["GENERALIZAR_UMA_MUDAN_A_POSTERIOR_CAMPANHA_SEM_COMPARA_O_QUE_CONTROLE_OUTRAS_CAUSAS_PLAUS_VEIS"]},"position":1},{"id":"v5-phil-argument-transfer-02","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"QUEUE_ALGORITHM_FAIRNESS","statement":"Uma plataforma diz que seu processo de seleção é justo porque todos recebem as mesmas perguntas. O que ainda falta para essa conclusão?","options":["Repetir que a regra é igual para todos.","Mostrar que o formulário tem muitas páginas.","Publicar apenas a quantidade total de inscritos.","Justificar por que perguntas iguais medem o critério relevante e examinar se condições de acesso ou interpretação produzem barreiras não relacionadas ao objetivo."],"correctAnswer":"Justificar por que perguntas iguais medem o critério relevante e examinar se condições de acesso ou interpretação produzem barreiras não relacionadas ao objetivo.","explanation":"Uniformidade do procedimento, sozinha, não prova que ele mede o mérito pretendido nem que todos conseguem demonstrá-lo em condições comparáveis.","errorFocus":"Deduzir justiça apenas da aplicação idêntica de uma regra.","hint":"Separe “mesmo procedimento” de “evidência válida do critério”; que condições podem afetar o resultado?","misconceptions":{"Repetir que a regra é igual para todos.":["DEDUZIR_JUSTI_A_APENAS_DA_APLICA_O_ID_NTICA_DE_UMA_REGRA"]},"position":2},{"id":"v5-phil-argument-transfer-03","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"RIVER_ACCESS_RESTRICTION","statement":"Um relatório mostra que restringir veículos em uma margem de rio reduz erosão. A equipe conclui que a restrição deve ser permanente para todas as áreas. Qual avaliação é mais completa?","options":["O dado apoia um efeito local, mas a regra geral também exige comparar áreas, alternativas, custos para grupos afetados e critérios de permanência.","A conclusão já está provada porque um local apresentou redução.","O dado deve ser ignorado porque foi coletado por uma equipe técnica.","Uma regra permanente é sempre melhor que uma medida temporária."],"correctAnswer":"O dado apoia um efeito local, mas a regra geral também exige comparar áreas, alternativas, custos para grupos afetados e critérios de permanência.","explanation":"O resultado é pertinente, mas seu alcance pode ser menor que o da conclusão. Uma política geral precisa considerar variação local e razões normativas.","errorFocus":"Estender um resultado localizado a uma regra geral sem justificar o alcance e os custos.","hint":"Compare a população observada com o grupo atingido pela conclusão e diferencie dado de recomendação.","misconceptions":{"A conclusão já está provada porque um local apresentou redução.":["ESTENDER_UM_RESULTADO_LOCALIZADO_A_UMA_REGRA_GERAL_SEM_JUSTIFICAR_O_ALCANCE_E_OS_CUSTOS"]},"position":3},{"id":"v5-phil-argument-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"MUSEUM_AUDIO_GUIDE","statement":"Um museu propõe substituir parte dos textos por áudio. Testes mostram maior permanência média perto das obras, mas algumas pessoas não conseguem ouvir o áudio. Que resposta argumentativa preserva o que os dados mostram sem exagerar?","options":["Concluir que toda pessoa aprende melhor por áudio.","Dizer que o áudio pode aumentar a permanência em certas condições, verificar acessibilidade e comparar formatos complementares antes de recomendar substituição total.","Descartar os testes porque nenhum dado pode informar decisões culturais.","Substituir todos os textos imediatamente, pois a permanência aumentou."],"correctAnswer":"Dizer que o áudio pode aumentar a permanência em certas condições, verificar acessibilidade e comparar formatos complementares antes de recomendar substituição total.","explanation":"O resultado sustenta uma afirmação limitada sobre permanência, não uma generalização sobre aprendizagem nem uma política que ignore acesso.","errorFocus":"Trocar um indicador observado por uma conclusão mais ampla sobre aprendizagem e adequação universal.","hint":"Nomeie exatamente o que foi medido e o que não foi medido.","misconceptions":{"Concluir que toda pessoa aprende melhor por áudio.":["TROCAR_UM_INDICADOR_OBSERVADO_POR_UMA_CONCLUS_O_MAIS_AMPLA_SOBRE_APRENDIZAGEM_E_ADEQUA_O_UNIVERSAL"]},"position":4},{"id":"v5-phil-argument-lock-01","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"DISTINGUISH","contextFamily":"DEDUCTIVE_VALIDITY","statement":"Considere: “Se o sensor está calibrado, ele registra valores dentro da tolerância. O sensor está calibrado. Logo, seus registros ficam dentro da tolerância.” O que a validade da forma permite afirmar?","options":["Que o sensor foi calibrado por uma pessoa certificada.","Que a conclusão é verdadeira mesmo se uma premissa for falsa.","Se as premissas forem verdadeiras, a conclusão segue; ainda é preciso verificar se o sensor está calibrado e se a regra é confiável.","Que os registros provam a regra geral por indução."],"correctAnswer":"Se as premissas forem verdadeiras, a conclusão segue; ainda é preciso verificar se o sensor está calibrado e se a regra é confiável.","explanation":"Validade trata da ligação entre premissas e conclusão. Ela não certifica por si só as premissas factuais.","errorFocus":"Confundir validade inferencial com verdade das premissas ou solidez do argumento.","hint":"Faça o teste condicional: supondo as premissas, seria possível a conclusão ser falsa?","misconceptions":{"Que o sensor foi calibrado por uma pessoa certificada.":["CONFUNDIR_VALIDADE_INFERENCIAL_COM_VERDADE_DAS_PREMISSAS_OU_SOLIDEZ_DO_ARGUMENTO"]},"position":1},{"id":"v5-phil-argument-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"WILDLIFE_CORRIDOR_POLICY","statement":"Um estudo registra mais travessias de animais em um corredor ecológico. A prefeitura conclui que deve desapropriar todos os terrenos vizinhos. Qual é a principal lacuna entre o dado e a decisão?","options":["O estudo não pode ser evidência porque observa animais.","A conclusão é dedutivamente válida por usar a palavra “deve”.","A medida está justificada porque toda desapropriação protege a natureza.","O dado descreve travessias, mas a desapropriação exige razões normativas e comparação de alternativas, necessidade, impacto e proporcionalidade."],"correctAnswer":"O dado descreve travessias, mas a desapropriação exige razões normativas e comparação de alternativas, necessidade, impacto e proporcionalidade.","explanation":"Uma observação pode informar uma política, mas não determina sozinha qual medida deve ser adotada nem se é a menos gravosa eficaz.","errorFocus":"Inferir uma obrigação específica diretamente de um dado descritivo sem explicitar valores e alternativas.","hint":"Identifique o fato observado, a ação recomendada e a premissa de valor que ligaria os dois.","misconceptions":{"O estudo não pode ser evidência porque observa animais.":["INFERIR_UMA_OBRIGA_O_ESPEC_FICA_DIRETAMENTE_DE_UM_DADO_DESCRITIVO_SEM_EXPLICITAR_VALORES_E_ALTERNATIVAS"]},"position":2},{"id":"v5-phil-argument-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"WATER_FILTER_CLAIM","statement":"Um anúncio afirma: “O filtro X remove 95% de partículas no ensaio descrito; portanto, atende ao padrão de potabilidade em qualquer casa.” Qual parte do raciocínio merece verificação primeiro?","options":["Se o ensaio mediu todos os contaminantes relevantes e se as condições de teste correspondem ao uso nas diferentes casas.","Se o anúncio usa uma fonte tipográfica sem serifa.","Se 95% é um número maior que 50%.","Se o filtro tem uma embalagem azul."],"correctAnswer":"Se o ensaio mediu todos os contaminantes relevantes e se as condições de teste correspondem ao uso nas diferentes casas.","explanation":"A conclusão amplia um resultado sobre partículas para um padrão de potabilidade em qualquer residência; é preciso verificar medida, contexto e alcance.","errorFocus":"Tratar um percentual sobre um indicador como prova de uma conclusão mais ampla.","hint":"Compare o que o ensaio mediu com o que a conclusão afirma.","misconceptions":{"Se o anúncio usa uma fonte tipográfica sem serifa.":["TRATAR_UM_PERCENTUAL_SOBRE_UM_INDICADOR_COMO_PROVA_DE_UMA_CONCLUS_O_MAIS_AMPLA"]},"position":1},{"id":"v5-phil-argument-review-02","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"SLEEP_MUSIC_CORRELATION","statement":"Uma pesquisa observa que estudantes que ouvem música ao estudar relatam dormir menos. Qual conclusão é sustentada com mais cautela?","options":["Ouvir música causa privação de sono em todos os estudantes.","Há uma associação nessa amostra; sem dados adicionais, não se sabe se a música causa menos sono nem em que direção a relação ocorre.","Dormir menos sempre faz alguém ouvir música.","A pesquisa prova que música não tem qualquer efeito."],"correctAnswer":"Há uma associação nessa amostra; sem dados adicionais, não se sabe se a música causa menos sono nem em que direção a relação ocorre.","explanation":"Uma associação observada não determina direção causal nem elimina fatores comuns, como rotina e carga de estudo.","errorFocus":"Converter correlação em causa ou escolher uma direção sem evidência.","hint":"Distinga associação observada de mecanismo causal e proponha uma explicação alternativa.","misconceptions":{"Ouvir música causa privação de sono em todos os estudantes.":["CONVERTER_CORRELA_O_EM_CAUSA_OU_ESCOLHER_UMA_DIRE_O_SEM_EVID_NCIA"]},"position":2},{"id":"v5-phil-argument-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"COMMUNITY_GARDEN_RULE","statement":"Um grupo diz que a horta comunitária deve manter uma regra de irrigação porque ela foi aprovada por unanimidade. Qual pergunta avalia melhor a justificativa?","options":["A unanimidade prova que a regra produzirá plantas saudáveis.","A votação torna irrelevantes as necessidades das plantas.","A regra distribui água de modo adequado diante das necessidades e limitações observadas, e quem não participou teve oportunidade de apresentar razões?","A regra deve ser rejeitada porque toda votação é injusta."],"correctAnswer":"A regra distribui água de modo adequado diante das necessidades e limitações observadas, e quem não participou teve oportunidade de apresentar razões?","explanation":"A unanimidade informa o resultado de um procedimento, mas não demonstra por si só adequação, evidência ou participação de todas as pessoas afetadas.","errorFocus":"Tratar consenso formal como prova suficiente da conclusão substantiva.","hint":"Pergunte o que a votação mede e quais razões ainda precisam ser avaliadas.","misconceptions":{"A unanimidade prova que a regra produzirá plantas saudáveis.":["TRATAR_CONSENSO_FORMAL_COMO_PROVA_SUFICIENTE_DA_CONCLUS_O_SUBSTANTIVA"]},"position":3},{"id":"v5-phil-argument-review-04","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"CIVIC_SURVEY_NONRESPONSE","statement":"Uma pesquisa municipal aponta apoio alto a uma praça nova, mas metade das pessoas convidadas não respondeu. O relatório afirma que “a maioria da cidade apoia o projeto”. Qual análise é mais forte?","options":["A conclusão é certa porque metade respondeu.","A pesquisa não tem nenhum valor em qualquer circunstância.","O apoio deve ser considerado universal até surgir uma reclamação.","A taxa e o padrão de não resposta podem alterar a representatividade; a conclusão deve ser limitada ou complementada por uma amostra adequada."],"correctAnswer":"A taxa e o padrão de não resposta podem alterar a representatividade; a conclusão deve ser limitada ou complementada por uma amostra adequada.","explanation":"A não resposta pode estar associada às opiniões ou às condições de acesso. Sem examinar quem ficou de fora, não se deve estender diretamente o resultado à cidade inteira.","errorFocus":"Ignorar viés de não resposta ao generalizar a amostra para a população.","hint":"Compare quem respondeu e quem não respondeu, e ajuste o alcance da afirmação.","misconceptions":{"A conclusão é certa porque metade respondeu.":["IGNORAR_VI_S_DE_N_O_RESPOSTA_AO_GENERALIZAR_A_AMOSTRA_PARA_A_POPULA_O"]},"position":4},{"id":"v5-phil-argument-review-05","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"EXPERT_CONFLICT_DISCLOSURE","statement":"Uma pesquisadora recomenda uma política de energia e recebe recursos de uma empresa do setor. O que a avaliação do argumento deve fazer com essa informação?","options":["Verificar se há conflito de interesse que afeta a confiabilidade ou seleção das evidências, sem substituir a análise das razões apresentadas.","Descartar automaticamente a conclusão porque a pesquisadora recebeu recursos.","Aceitar a conclusão porque toda especialista é imparcial.","Atacar a pesquisadora sem examinar método ou evidências."],"correctAnswer":"Verificar se há conflito de interesse que afeta a confiabilidade ou seleção das evidências, sem substituir a análise das razões apresentadas.","explanation":"A relação pode ser relevante para avaliar transparência e confiabilidade, mas não é, sozinha, refutação do conteúdo do argumento.","errorFocus":"Confundir um possível conflito de interesse com prova automática de falsidade ou ignorá-lo completamente.","hint":"Pergunte se a relação pode influenciar evidência ou método e examine também esses elementos.","misconceptions":{"Descartar automaticamente a conclusão porque a pesquisadora recebeu recursos.":["CONFUNDIR_UM_POSS_VEL_CONFLITO_DE_INTERESSE_COM_PROVA_AUTOM_TICA_DE_FALSIDADE_OU_IGNOR_LO_COMPLETAMENTE"]},"position":5},{"id":"v5-phil-argument-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"LIBRARY_AND_PARK_ANALOGY","statement":"Uma associação compara o uso noturno de uma biblioteca ao uso de um parque e conclui que a mesma regra de fechamento deve valer para ambos. Qual é a melhor avaliação da comparação?","options":["A comparação é forte porque biblioteca e parque são espaços públicos.","A semelhança de uso público não basta; diferenças de serviço, riscos, estrutura e alternativas precisam ser ligadas ao critério da regra.","A analogia é inválida porque os lugares têm nomes diferentes.","A regra deve ser idêntica sempre que duas áreas forem abertas ao público."],"correctAnswer":"A semelhança de uso público não basta; diferenças de serviço, riscos, estrutura e alternativas precisam ser ligadas ao critério da regra.","explanation":"Uma analogia depende de semelhanças relevantes para a conclusão e deve considerar diferenças que afetem segurança, finalidade e serviço.","errorFocus":"Aceitar uma analogia por compartilhar apenas uma característica genérica.","hint":"Pergunte quais características justificariam a mesma regra e quais diferenças poderiam mudar a decisão.","misconceptions":{"A comparação é forte porque biblioteca e parque são espaços públicos.":["ACEITAR_UMA_ANALOGIA_POR_COMPARTILHAR_APENAS_UMA_CARACTER_STICA_GEN_RICA"]},"position":6},{"id":"v5-phil-argument-review-07","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"HEARING_ACCESSIBILITY_POLICY","statement":"Uma audiência sobre transporte registra que várias pessoas não conseguiram acompanhar as falas por falta de legendas. A secretaria conclui que legendas devem ser oferecidas em toda reunião pública. Qual avaliação combina melhor evidência e justificativa?","options":["Os relatos provam que toda reunião terá o mesmo problema e dispensam qualquer avaliação.","A secretaria deve ignorar os relatos porque não são um experimento controlado.","Os relatos identificam uma barreira; a recomendação pode ser justificada por participação e acesso, avaliando formatos, custos e exceções sem exigir que cada pessoa prove a necessidade em público.","A recomendação é falsa porque participação é uma opinião pessoal."],"correctAnswer":"Os relatos identificam uma barreira; a recomendação pode ser justificada por participação e acesso, avaliando formatos, custos e exceções sem exigir que cada pessoa prove a necessidade em público.","explanation":"Relatos podem revelar uma barreira real, embora não estimem sozinhos sua frequência. Uma política ainda precisa explicitar o princípio e comparar meios de implementação.","errorFocus":"Tratar evidência qualitativa como universal ou descartá-la por não ser experimental.","hint":"Diga o que os relatos mostram, o que não estimam e qual razão normativa apoia a política.","misconceptions":{"Os relatos provam que toda reunião terá o mesmo problema e dispensam qualquer avaliação.":["TRATAR_EVID_NCIA_QUALITATIVA_COMO_UNIVERSAL_OU_DESCART_LA_POR_N_O_SER_EXPERIMENTAL"]},"position":7},{"id":"v5-phil-argument-review-08","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"BIKE_LANE_PILOT","statement":"Após um teste de ciclovia, comerciantes relatam menos vagas para clientes e hospitais registram mais viagens de bicicleta. Qual conclusão é mais bem calibrada para decidir a próxima etapa?","options":["Expandir imediatamente porque um indicador melhorou.","Encerrar imediatamente porque um grupo relatou custo.","Concluir que nenhuma decisão é possível enquanto não houver certeza absoluta.","Os resultados apontam efeitos diferentes; medir duração, locais e grupos afetados e comparar alternativas antes de ampliar ou encerrar o projeto."],"correctAnswer":"Os resultados apontam efeitos diferentes; medir duração, locais e grupos afetados e comparar alternativas antes de ampliar ou encerrar o projeto.","explanation":"Evidência mista deve informar trade-offs, não ser reduzida ao resultado preferido. Um piloto pode ser ajustado e acompanhado com critérios claros.","errorFocus":"Selecionar apenas a evidência que favorece uma posição ou exigir certeza impossível antes de decidir.","hint":"Integre os dois resultados, identifique quem recebe benefícios e custos e proponha um próximo teste informativo.","misconceptions":{"Expandir imediatamente porque um indicador melhorou.":["SELECIONAR_APENAS_A_EVID_NCIA_QUE_FAVORECE_UMA_POSI_O_OU_EXIGIR_CERTEZA_IMPOSS_VEL_ANTES_DE_DECIDIR"]},"position":8}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-philosophy-evaluate-argument',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-philosophy-evaluate-argument' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'PHILOSOPHY', 'ARGUMENTO', 'avaliacao de premissas, inferencias e conclusoes',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

